/**
 * Generates _bmad-output/planning-artifacts/august-6th-updates-handoff.md.
 *
 * Run from the api repo root:  node ralph/generate-handoff.mjs
 * Run ralph/generate.mjs FIRST — this reads the rendered per-workstream files.
 */
import { readFileSync, writeFileSync, readdirSync } from 'node:fs'

const RALPH = '/Users/verumoffice/atelier-api/ralph'
const REPO_PATHS = {
  'atelier-api': '/Users/verumoffice/atelier-api',
  'atelier-crm': '/Users/verumoffice/atelier-crm',
  'atelier-storefront': '/Users/verumoffice/atelier-storefront',
}
const WAVE = {
  'w1-foundations': 1, 'w8-colour-files': 1, 'w9-scanner-spike': 1,
  'w2-crud': 2, 'w3-suppliers': 2, 'w7-featured': 2,
  'w4-samples': 3, 'w6-category-export': 3,
  'w5-reporting': 4,
}

const slice = (text, start, end) => {
  const a = text.split(start)[1]
  return end ? a.split(end)[0] : a
}

const OUT = '/Users/verumoffice/atelier-api/_bmad-output/planning-artifacts/august-6th-updates-handoff.md'

const PREAMBLE = "# Handoff — Atelier \"August 6th updates\"\n\nNine workstreams across three repos. Each section below is self-contained: run its **setup script**,\nthen either launch the Ralph loop or paste **Block B** into a fresh Claude Code instance — both use\nthe same instructions from `ralph/<ws>/CLAUDE.md`.\n\n**Never copy-paste a fenced block into a terminal.** The triple backticks open a command\nsubstitution and bash swallows the block, which half-executes it. Run the scripts.\n\nGenerated by `ralph/generate-handoff.mjs` from `ralph/generate.mjs`s spec and the rendered\n`ralph/<ws>/CLAUDE.md`. To change a brief, edit the spec and regenerate — do not hand-edit this file.\n\n## Before anything\n\nWave 0 is done: the three dirty working trees are parked on branches, `august-6th-updates` exists\nin all three repos, and BMAD v6.10.0 is installed. `main`/`master` are untouched and must stay that\nway.\n\nBaseline SHAs — these must be unchanged when the work is finished:\n\n| Repo | Branch | SHA |\n|---|---|---|\n| atelier-api | main | `5d19d48a61885cac7939f4349c5c34f5690a765f` |\n| atelier-crm | **master** | `0989524f6064fb821694998c2054ee0fd4aebe09` |\n| atelier-storefront | main | `f5cfc5eae3197a3a8c58db3821138425a3c6d9d6` |\n\nNote the CRM's default branch is `master`, not `main`. Nothing may assume otherwise.\n\n## Ground rules\n\n- **Nothing touches `main`/`master`.** The live sites and API run off them. `ralph.sh` blocks\n  `git push`, `rebase`, `merge`, `stash`, `reset`, `switch` and `branch` at the tool level, not just\n  in the prompt. A human merges into `august-6th-updates`.\n- **No `--dangerously-skip-permissions`.** The loop runs a scoped allowlist. Expect W1 — which runs\n  alone and supervised — to stall once or twice on a legitimate command; widen `ALLOWED` in\n  `ralph.sh` rather than reaching for `bypassPermissions`.\n- **One database per workstream.** The API test suite migrates a real Postgres and node-pg-migrate\n  takes an advisory lock, so two loops sharing `atelier_dev` deadlock and cross-contaminate\n  fixtures — failures that read as code bugs and send an agent off fixing working code.\n- **There is no typecheck in any repo.** All three are plain JavaScript. Never write \"Typecheck\n  passes\" into an acceptance criterion.\n- **Concurrency cap: 3 loops.** A review-throughput limit, not a technical one.\n\n## Wave schedule\n\n```\nWave 1   w1-foundations   ALONE and supervised — everything depends on it\n         w8-colour-files  concurrent, disjoint file footprint\n         w9-scanner-spike concurrent, docs only, NOT under Ralph\n\nWave 2   w2-crud | w3-suppliers | w7-featured\n\nWave 3   w4-samples | w6-category-export\n\nWave 4   w5-reporting\n```\n\nMerge order within a workstream is always **api → crm → storefront**. A merged CRM screen calling a\nnot-yet-merged endpoint 404s, and the next workstream's agent will misdiagnose it.\n\n## After each loop finishes\n\n1. `./atelier-api/ralph/verify.sh <ws>` from the workstream root — commit the log. That turns\n   \"gates were green\" from a claim into an artefact.\n2. Review in a **fresh** Claude instance in the same worktree: the `bmad-code-review` skill, then\n   the `code-reviewer` agent on the branch diff; add `database-reviewer` if `migrations/` changed\n   and `security-reviewer` for W2, W3, W5 and W8.\n3. Cross-repo drift check: every API path in the CRM/storefront diff must resolve to a route on the\n   branch or on `august-6th-updates`.\n4. Merge api → crm → storefront, then tear down the worktree and drop the database.\n\n## Reference\n\n| What | Where |\n|---|---|\n| Requirements | `_bmad-output/planning-artifacts/prd.md` |\n| Architecture | `_bmad-output/planning-artifacts/architecture.md` |\n| Epics (1:1 with workstreams) | `_bmad-output/planning-artifacts/epics.md` |\n| Cross-repo rules and gates | `_bmad-output/project-context.md` |\n| Status board | `_bmad-output/implementation-artifacts/sprint-status.yaml` |\n| Loop mechanics | `ralph/README.md` |\n\n## The nine briefs\n"

const briefs = []
for (const ws of readdirSync(RALPH).filter((d) => /^w\d/.test(d)).sort()) {
  const prd = JSON.parse(readFileSync(`${RALPH}/${ws}/prd.json`, 'utf8'))
  const md = readFileSync(`${RALPH}/${ws}/CLAUDE.md`, 'utf8')

  const repos = [...new Set(prd.userStories.flatMap((s) => s.repos))]
  const db = `atelier_${ws.slice(0, 2)}`
  const iters = Math.ceil(prd.userStories.length * 1.5)
  const name = prd.project.split('— ').pop()
  const wsId = name.split(' ')[0]
  const lines = prd.description.split('\n')
  const goal = lines[0]
  const requires = (lines.find((l) => l.startsWith('Requires:')) || '').replace('Requires: ', '')
  const blocks = (lines.find((l) => l.startsWith('Blocks:')) || '').replace('Blocks: ', '')
  const allowed = slice(md, '### Files you MAY touch\n', '\n\n')
  const forbidden = slice(md, '### Files you MUST NOT touch\n', '\n\n')
  const gates = slice(slice(md, '## Step 3 — Gates'), '```bash\n', '```').trim()
  const readAlso = [
    repos.includes('atelier-crm') && '`atelier-crm/CLAUDE.md`',
    repos.includes('atelier-storefront') && '`atelier-storefront/CLAUDE.md`',
  ].filter(Boolean)

  const o = []
  o.push(`\n---\n`)
  o.push(`## ${name} — \`${ws}\`  ·  Wave ${WAVE[ws]}  ·  ${prd.userStories.length} stories\n`)
  o.push(`${goal}\n`)
  o.push(`**Requires:** ${requires}  \n**Blocks:** ${blocks}  \n**Repos:** ${repos.join(', ')}\n`)
  if (ws === 'w9-scanner-spike') {
    o.push(
      `> **Do not run this one under Ralph.** A research task has no gates, so a loop has nothing\n` +
        `> to verify against and would burn its budget. Run it as one supervised session on\n` +
        `> \`aug6/w9-scanner-spike\` in the main api checkout.\n`,
    )
  }

  o.push(`### Block A — SETUP\n`)
  o.push(
    `**Run the script. Do not copy-paste the commands** — pasting a fenced block into bash opens a\n` +
      `backtick command substitution that swallows the whole thing and half-executes the setup.\n`,
  )
  o.push('```\n' + `/Users/verumoffice/atelier-api/ralph/${ws}/setup.sh\n` + '```\n')
  o.push(
    `Creates ${repos.length} worktree${repos.length > 1 ? 's' : ''} on \`aug6/${ws}\`, symlinks \`node_modules\`, ` +
      `copies \`.env\`, creates the \`${db}\` database and repoints \`DATABASE_URL\` at it, migrates, and runs ` +
      `every gate. It refuses to continue if \`DATABASE_URL\` was not rewritten — a half-run setup that ` +
      `leaves it on \`atelier_dev\` would make the loop migrate the shared database.\n`,
  )

  o.push(`Then launch:\n`)
  o.push('```\n' + `cd /Users/verumoffice/atelier-worktrees/${ws}\n./atelier-api/ralph/ralph.sh ${ws} ${iters}\n` + '```\n')
  o.push(`After the branch is merged, tear down:\n`)
  o.push('```\n' + `/Users/verumoffice/atelier-api/ralph/${ws}/teardown.sh\n` + '```\n')
  o.push(
    `Teardown refuses if any repo has uncommitted changes or commits not yet in \`august-6th-updates\`.\n`,
  )

  o.push(`### Block B — BRIEF (paste this whole block into a fresh Claude Code instance)\n`)
  const b = []
  b.push('````markdown')
  b.push(`# TASK: ${name} (Atelier, "August 6th updates")\n`)
  b.push(`## Goal\n${goal}\n`)
  b.push(`## Where you are working`)
  b.push(`- Working directory: \`/Users/verumoffice/atelier-worktrees/${ws}\` — **not a git repo, no CLAUDE.md, nothing auto-loads**`)
  for (const r of repos) b.push(`- \`${r}/\` — worktree of ${REPO_PATHS[r]}, branch \`aug6/${ws}\``)
  b.push(`- Merge target: \`august-6th-updates\` in each repo. **Never touch \`main\`/\`master\`** — the live sites and API run off them.`)
  b.push(`- Database: \`${db}\` (already set in atelier-api/.env). Never use \`atelier_dev\`; other loops use theirs.`)
  b.push(`- **These are plain-JavaScript repos. There is no typecheck anywhere. Do not look for one.**\n`)
  b.push(`## Read these first, in this order`)
  b.push(`1. \`atelier-api/ralph/${ws}/progress.txt\` — the \`## Codebase Patterns\` block at the top`)
  b.push(`2. \`atelier-api/ralph/${ws}/prd.json\` — your story list`)
  b.push(`3. \`atelier-api/ralph/${ws}/CLAUDE.md\` — your full operating instructions; this brief is a summary of it`)
  b.push(`4. \`atelier-api/_bmad-output/project-context.md\` — cross-repo rules and the real gates`)
  b.push(`5. \`atelier-api/CLAUDE.md\`${readAlso.length ? ` and ${readAlso.join(' and ')}` : ''}`)
  b.push(`6. \`atelier-api/_bmad-output/planning-artifacts/architecture.md\` — only the sections your story names\n`)
  b.push(`## Dependencies\n- **Requires:** ${requires}\n- **Blocks:** ${blocks}\n`)
  b.push(`## Files you MAY touch\n${allowed}\n`)
  b.push(`## Files you MUST NOT touch\n${forbidden}`)
  b.push(`- \`atelier-api/incoming/**\` — the client's only copy of real data. READ ONLY.`)
  b.push(`- Any \`.env\`. Any \`package.json\` dependency — \`node_modules\` is a symlink to the main checkout.\n`)
  b.push(`## Gates (run before every commit; all must exit 0)\n\`\`\`bash\n${gates}\n\`\`\``)
  b.push(`Migration stories also: run \`npm run migrate\` twice and prove the second run is a no-op.\n`)
  b.push(`## How to work`)
  b.push(`One story per turn — the lowest \`priority\` in prd.json where \`passes\` is false and \`notes\` does not start \`BLOCKED:\`. Implement it, run the gates, then commit:\n`)
  b.push(`    feat(api): [${wsId}-US-XXX] - <Story Title>\n`)
  b.push(`Use \`crm\`/\`store\` as the scope for those repos. A story touching two repos produces two commits with the SAME \`[${wsId}-US-XXX]\` tag — that tag is how a reviewer reassembles a cross-repo change.\n`)
  b.push(`The same commit must also carry: \`prd.json\` \`passes: true\`, the \`sprint-status.yaml\` flip, and the \`progress.txt\` append block with a **Learnings:** section.\n`)
  b.push(`**NEVER** run \`git push\`, \`rebase\`, \`merge\`, \`stash\`, \`reset\`, \`switch\`, \`branch\` or any \`--force\`. A human merges. These are blocked at the tool level — a denial is the system working, not an obstacle to route around.\n`)
  b.push(`## When a story cannot pass`)
  b.push(`Two honest attempts, then set \`notes: "BLOCKED: <reason>"\`, write \`ralph/${ws}/BLOCKED.md\`, revert the partial code, commit only the bookkeeping, and move on. Never retry a blocked story. Anything needing a product decision — a schema shape architecture.md does not cover, a file another workstream owns, a dependency you think you need — is BLOCKED. Do not decide it yourself.\n`)
  b.push(`## Done means`)
  b.push(`All ${prd.userStories.length} stories \`passes: true\`, no BLOCKED.md, gates green, \`PR-BODY.md\` written, then reply with:\n`)
  b.push(`    <promise>COMPLETE</promise>`)
  b.push('````')
  o.push(b.join('\n') + '\n')

  briefs.push(o.join('\n'))
}

writeFileSync(OUT, PREAMBLE + briefs.join('\n'))
console.log(`Wrote ${OUT}\n${briefs.length} briefs, ${(PREAMBLE + briefs.join('')).length} chars`)
